CREATE PERFETTO TABLE present AS SELECT DISTINCT a.ts+a.dur ts FROM actual_frame_timeline_slice a JOIN process p USING(upid) WHERE p.name='/system/bin/surfaceflinger' AND a.dur>0 AND a.present_type IN ('On-time Present','Late Present','Early Present');
CREATE PERFETTO TABLE gaps AS SELECT ts,lag(ts) OVER (ORDER BY ts) prev_ts FROM present;
CREATE PERFETTO TABLE worst AS SELECT g.prev_ts ts,g.ts-g.prev_ts dur,q.name phase FROM gaps g JOIN slice q ON q.name GLOB 'return|*' AND g.prev_ts>=q.ts AND g.ts<q.ts+q.dur ORDER BY dur DESC LIMIT 1;
SELECT phase,round(dur/1e6,2) gap_ms FROM worst;
SELECT p.name,t.name,s.name,round((s.ts-w.ts)/1e6,2) rel_ms,round(s.dur/1e6,2) ms FROM slice s JOIN thread_track tt ON tt.id=s.track_id JOIN thread t USING(utid) JOIN process p USING(upid),worst w WHERE s.dur>5000000 AND s.ts<w.ts+w.dur AND s.ts+s.dur>w.ts AND ((p.name='/system/bin/surfaceflinger' AND t.tid=p.pid) OR (p.name LIKE '%display.composer-service' AND t.tid=p.pid) OR (p.name='com.android.launcher' AND t.name='RenderThread')) ORDER BY s.ts LIMIT 28;
SELECT p.name,t.name,st.state,round(sum(min(st.ts+st.dur,w.ts+w.dur)-max(st.ts,w.ts))/1e6,2) ms FROM thread_state st JOIN thread t USING(utid) JOIN process p USING(upid),worst w WHERE st.ts<w.ts+w.dur AND st.ts+st.dur>w.ts AND st.dur>0 AND ((p.name='/system/bin/surfaceflinger' AND t.tid=p.pid) OR (p.name LIKE '%display.composer-service' AND t.tid=p.pid) OR (p.name='com.android.launcher' AND t.name='RenderThread')) GROUP BY t.utid,st.state ORDER BY p.name,t.name,ms DESC;
